 function renderChecks(){const checks=[];if(imported){const missing=plan.faces.filter(f=>f.importedStatus!=='assigned').length;if(missing)checks.push(`${missing} élévation${missing>1?'s':''} non importée${missing>1?'s':''} : les totaux couvrent uniquement les surfaces relevées. Les autres faces ne sont pas assimilées à zéro.`);if(!currentInput.soffits.length)checks.push('Aucune surface de soffite relevée dans ce PDF pour le moment. La quantité reste à définir.');checks.push('Les contours issus de la détection sont des propositions. Vérifier les fenêtres et les zones, puis personnaliser les matériaux proposés avant de préparer la liste.');}
  const uncal=Object.values(state.calibrations).filter(c=>!c.verified).length;if(uncal)checks.push(`${uncal} échelles restent à vérifier sur les cotes du document. Les contours masqués par les légendes doivent être validés.`);
  if(!state.geometry.confirmed)checks.push(imported?'Retraits, retours et profondeurs : à renseigner depuis le plan du client; aucune mesure de l’exemple MIR n’est utilisée.':'Retrait : profondeur estimée à 2 pi et hauteur de travail; confirmer ces cotes et la géométrie de l’étage.');
  const ns=currentInput.soffits.filter(s=>s.enabled!==false&&(!Number.isFinite(s.depthIn)||!Number.isFinite(s.fasciaLengthFt)));if(ns.length)checks.push(`${ns.length} sections de soffite avec une dimension manquante. Le total de soffite affiché est partiel.`);
  const shapes=currentInput.windows.filter(w=>w.enabled&&w.special);if(shapes.length)checks.push(`${shapes.length} fenêtres à tête triangulaire : rampants et goutte d’eau de tête à détailler; la règle rectangulaire ne suffit pas.`);
  checks.push('L de fenêtre : +3 po au total, avec ou sans bas ventilé. Répartition proposée : 1 po par morceau à trois côtés, ou 1½ po par jambage avec bas ventilé. Toutes les moulures utilisent du stock de 120 po, sauf le J à soffite de 144 po.');
  if(currentInput.windows.some(w=>w.enabled&&w.trimMode==='material'))checks.push('Contour de fenêtre en matériau : deux gouttes distinctes sont prévues, baie + surplus puis largeur extérieure du contour + surplus. Cette hypothèse reste modifiable dans les dimensions et surplus de la section Fenêtres.');
  checks.push('Anti-rongeur au-dessus des fenêtres et en bas des murs; ventilation haute limitée aux vrais bords supérieurs des murs hors brique et pignons. Confirmer les conditions de pose et les profils compatibles avec chaque revêtement.');
  if(result.panels.some(p=>(p.cells||[]).some(c=>c.special)))checks.push('Panneaux découpés : les enveloppes et joints sont limités aux contours visibles, aux ouvertures et aux accents. Valider les détails de coupe, les jeux et le sens du fini. La rotation de débit ne change pas les orientations de pose autorisées.');
  const missing=currentInput.panels.filter(p=>!p.stockKnown||(p.layout.mode==='product'&&p.layout.complete!==true));if(missing.length)checks.push(`${missing.length} zones de panneaux attendent un format physique, une orientation ou une échelle confirmés. Leur grille automatique et la conformité des coupes restent à valider.`);
  const unique=new Set();for(const w of result.warnings||[]){const text=w.message||w.code;if(!unique.has(text)){unique.add(text);checks.push(text);}}
  checks.push('Les petites projections visibles sur les élévations latérales ne sont pas ajoutées comme des murs de profondeur connue. Les deux retours centraux sont comptés séparément, une seule fois.');
  checks.push('Valider les recouvrements, formats utiles, conditionnements, compatibilités et disponibilités avant commande. Les pertes ajoutées ne remplacent pas le plan de coupe.');
  if(cornerPlan){checks.push(...(cornerPlan.pendingSources||[]).map(p=>p.message||p),...(cornerPlan.warnings||[]));if(!state.corners.reviewed)checks.push('Coins de 10 pi : vérifier le relevé proposé et les raccords.');}if(cutPlan&&!cutPlan.complete)checks.push('Débit fibro partiel : résoudre les pièces non placées avant de commander le nombre final de feuilles.');
  $('#check-list').innerHTML=checks.map(s=>`<li>${esc(s)}</li>`).join('');
 }
