  rows.push([],['LISTE DES COUPES'],['Élévation','Profil','Fabricant','Référence matériau','Référence couleur','Couleur fabricant','Source','Longueur de coupe','Unité','Longueur de stock']);for(const p of result.pieces||[])rows.push([currentInput.faces.find(f=>f.key===p.face)?.name||p.face,profileNames[p.profile]||p.profile,p.brand,p.materialId,p.colorId,p.colorName,p.sourceId,p.lengthIn,'po',p.stockIn]);
