  rows.push([],['FEUILLES DE FIBROCIMENT — QUANTITÉ SELON LE DÉBIT'],['Produit / finition','Format po','Quantité connue','Repères','État']);for(const r of cutSheetRows())rows.push([cutMaterialLabel(r),r.widthIn+' × '+r.heightIn,r.quantity,r.labels.join(' / '),cutPlan.complete?'À valider':'Quantité partielle']);
  rows.push([],['MORCEAUX FIBROCIMENT'],['Repère','Façade','Zone','Produit / couleur','Largeur po','Hauteur po','Bas usine exigé','Feuille','État','Révision']);for(const p of cutPlan?.pieces||[]){const sheet=cutPlan.sheets.find(s=>s.placements.some(x=>x.pieceId===p.id)),pending=cutPlan.unplaced.find(u=>u.pieceId===p.id);rows.push([p.label,p.face,p.zoneId,cutMaterialLabel(p),p.widthIn,p.heightIn,p.requireFactoryBottom?'Oui':'Non',sheet?.label||'',pending?.messages?.join(' / ')||p.status,cutPlan.revision]);}
  download('MIR_Estimation_materiaux.csv','text/csv;charset=utf-8','\uFEFF'+rows.map(r=>r.map(csvValue).join(';')).join('\r\n'));toast('Liste et pièces de coupe exportées. Statut : estimation à valider.');
