 function snapshotExportFaces({mode='complete',includeReturns=false}={}){const byFace=faceMaterialRows(),keys=plan.faces.map(f=>f.key);if(includeReturns&&currentInput.faces.find(f=>f.key==='returns')?.zones.length)keys.push('returns');return keys.map(key=>{const f=cutFaces.find(x=>x.key===key)||currentInput.faces.find(x=>x.key===key),items=overlayItems(f),notes=notesFor(f),summary=[`Échelle de travail : ${fmt(f.feetPerPixel,5)} pi / pixel · ${key==='returns'?state.geometry.confirmed?'retours confirmés':'retours à vérifier':state.calibrations[key]?.verified?'contrôle déclaré effectué':'à valider sur le PDF'}.`];
   for(const n of notes)summary.push({label:`${n.label} ${n.text}`,color:'#b76723'});
   for(const [i,z] of E.paintOrder(f).entries())summary.push(`${mode==='complete'?'Z'+(i+1)+'. ':''}${z.name||z.id} : ${byMaterial.get(z.selection?.materialId)?.name||'Matériau à définir'} · ${colorLabel(z.selection||{})}.`);
   for(const r of byFace.filter(x=>x.face===f.key&&(mode==='complete'||x.hasArea)))summary.push(`${byMaterial.get(r.materialId)?.name||'Profil atelier'} · ${colorLabel(r)} : ${r.hasArea?fmt(r.area,2)+' pi² nets; ':''}${mode==='complete'?fmt(r.lengthFt,2)+' PL':''}${r.partial?' connus + quantités à définir':''}.`);
   if(mode==='complete'){
    for(const [i,item] of items.entries())summary.push({label:`${i+1}. ${profileNames[item.profile]||item.profile} · ${item.label} : ${fmt(item.lengthFt,2)} PL`,color:profileColors[item.profile]||'#49633c'});
    for(const line of currentInput.segments.filter(s=>s.face===f.key&&s.enabled!==false&&!s.points))summary.push(`Sans position dessinée : ${line.name} · ${fmt(line.displayLengthFt,2)} PL.`);
    for(const p of result.panels.filter(p=>p.face===f.key))summary.push(`Calepinage ${p.zoneId} : ${(p.cells||[]).length} cellules. Les morceaux physiques et leurs feuilles portent des repères P et F; rotation selon le grain et le bas d’usine.`);
    for(const b of result.boards.filter(p=>p.face===f.key))summary.push(`CanExel ${b.zoneId} : segments ${b.cells.map(c=>fmt(c.lengthIn,1)+(c.fits?'':' — trop long')).join(' / ')} po; maximum ${b.maximumIn} po.`);
    for(const c of (cornerPlan?.rows||[]).filter(c=>c.face===f.key))summary.push(`${c.name} : ${fmt(c.lengthFt,2)} pi × ${c.count} · ${c.stockCount??'à définir'} longueurs de 10 pi.`);
    if(f.key==='front')for(const r of byFace.filter(x=>x.face==='returns'))summary.push(`Retours centraux développés sur la page dédiée : ${byMaterial.get(r.materialId)?.name||'profil'} · ${colorLabel(r)} · ${r.hasArea?fmt(r.area,2)+' pi²; ':''}${fmt(r.lengthFt,2)} PL.`);
    summary.push('Pi² = surfaces; PL = longueurs. Bandeaux et contours : surfaces informatives déduites du parement, commande par coupes linéaires. Moulures et coins 120 po; J de soffite 144 po.');
   }
   summary.push('Utiliser les cotes indiquées : dessin non à l’échelle d’impression. Mesures, contours et détails de pose à valider avant fabrication.');
   return{key:f.key,name:f.name,bbox:f.bbox,feetPerPixel:f.feetPerPixel,svg:annotatedSvg(f,{allLabels:mode==='complete',panelLabels:false,cutLabels:false,profiles:mode==='complete',zoneLabels:mode==='complete'}),summary};
  });}
