 function cornerPdfPages(mode='complete'){if(!cornerPlan?.rows.length)return[];const rows=copy(cornerPlan.rows),pages=[];for(let offset=0;offset<rows.length;offset+=10){const part=rows.slice(offset,offset+10);let body='<rect width="1500" height="900" fill="white"/><text x="30" y="52" font-size="32" font-weight="700">COINS · LONGUEURS DE 10 PI</text><text x="30" y="91" font-size="20" fill="#61715d">'+esc(`${cornerPlan.physicalCornerCount} coins physiques · recouvrement ${fmt(state.corners.overlapIn,2)} po · ${state.corners.reviewed?'relevé déclaré vérifié':'relevé à confirmer'}`)+'</text>';const cols=[30,560,880,1060,1225];['Coin / emplacement','Type et finition','Hauteur','Nombre','Longueurs 10 pi'].forEach((t,i)=>body+=`<text x="${cols[i]}" y="138" font-size="19" font-weight="700">${esc(t)}</text>`);part.forEach((c,i)=>{const y=185+i*61;body+=`<path d="M30 ${y+28}H1470" stroke="#dae2d5"/><text x="30" y="${y}" font-size="19">${esc(c.name)}</text><text x="560" y="${y}" font-size="18">${c.kind==='inside'?'Intérieur':'Extérieur'}</text><text x="560" y="${y+22}" font-size="15">${esc((c.colorName||'Finition à confirmer').slice(0,36))}</text><text x="880" y="${y}" font-size="20">${fmt(c.lengthFt,2)} pi</text><text x="1060" y="${y}" font-size="20">${c.count??'?'}</text><text x="1225" y="${y}" font-size="23" font-weight="700">${c.stockCount??'À définir'}</text>`;});body+='<text x="30" y="848" font-size="18" fill="#61715d">Chutes non partagées entre coins. Valider les jonctions, les recouvrements et les finitions.</text>';pages.push({key:'corners-'+offset,name:'Coins · '+(pages.length+1),layout:'wide',svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1500 900" font-family="Arial,sans-serif" fill="#263b2a">${body}</svg>`,summary:[],footerNote:mode==='site'?'Feuille chantier · coins de 10 pi':'Estimation de travail · relevé des coins à valider'});}return pages;}
